    body = ''.join('<tr>'+''.join('<td>'+escape(str(v))+'</td>' for v in row)+'</tr>' for row in rows)
    return '<div class="table"><table><thead><tr>'+head+'</tr></thead><tbody>'+body+'</tbody></table></div>'

