class PlainText(HTMLParser):
    def __init__(self):
        super().__init__();self.parts=[]
    def handle_data(self,data):
        self.parts.append(data)
    def handle_endtag(self,tag):
        if tag in {'p','h1','h2','h3','li','tr','figcaption'}:self.parts.append('\n')
        elif tag in {'td','th'}:self.parts.append(' | ')

parser=PlainText();parser.feed(body)
(DEST/'karaoke_v5_report.txt').write_text(''.join(parser.parts),encoding='utf-8')
